INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','inversion','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"inversion","title":"Inversion after negatives and in conditionals","level":"C1","order":62,"summary":"Recognise formal emphasis that places an auxiliary before the subject, and conditional forms that omit if.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Negative or limiting openings","Move only the first auxiliary","Conditional inversion without if","Scope of only and not until"],"rules":[{"title":"Negative or limiting openings","explanation":"After fronted negative or limiting expressions such as never, rarely and only then, formal English often uses **auxiliary–subject inversion** in the main clause. Add do-support if the original lexical verb has no auxiliary.","pattern":"**Rarely does she complain**.","commonMistakes":["Rarely she complains does not follow the standard emphatic inversion pattern after fronted rarely."],"examples":["Use formal inversion: “Rarely **does she prepare** the visitor guide without help.”","Use formal inversion: “Rarely **does she restore** the old portrait without help.”"],"skill":"form"},{"title":"Move only the first auxiliary","explanation":"If a verb phrase already has auxiliaries, move just the first one before the subject. Keep later auxiliaries and the main verb after the subject. The form resembles a question, but the sentence is still a statement.","pattern":"**Never have I been** so surprised.","commonMistakes":["Never have been I ... moves too much of the verb phrase before the subject."],"examples":["Use formal inversion: “Never **have they prepared** the visitor guide so quickly.”","Use formal inversion: “Never **have they restored** the old portrait so quickly.”"],"skill":"meaning"},{"title":"Conditional inversion without if","explanation":"Formal conditionals can omit if and begin with **had**, **were** or **should**. Had I known means if I had known. Were she to leave presents a hypothetical condition; should you need help presents a possible contingency.","pattern":"**Had I known**, I would have called.","commonMistakes":["Do not keep if as well as using this inverted conditional pattern."],"examples":["Replace “If we had prepared the visitor guide”: “**Had we prepared** the visitor guide, we would have finished earlier.”","Replace “If we had restored the old portrait”: “**Had we restored** the old portrait, we would have finished earlier.”"],"skill":"contrast"},{"title":"Scope of only and not until","explanation":"An opening such as Only after the meeting or Not until she arrived triggers inversion in the **main clause**, not in the subordinate time clause. Only modifying the subject does not normally trigger this inversion.","pattern":"Only after she arrived **did we begin**.","commonMistakes":["Only the manager knew has no inversion because only modifies the subject itself."],"examples":["Use inversion in the main clause: “Only after the call **did she prepare** the visitor guide.”","Use inversion in the main clause: “Only after the call **did she restore** the old portrait.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-inversion","bc-inverted-conditions"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"db40df01-59b2-5458-ac9b-986515f21500","topicSlug":"inversion","level":"C1","prompt":"Use formal inversion: “Rarely ____ the visitor guide without help.”","choices":[{"id":"A","text":"does she prepares"},{"id":"B","text":"she does prepare"},{"id":"C","text":"does she prepare"},{"id":"D","text":"she prepares"}],"answerId":"C","hint":"A fronted negative-frequency expression triggers **auxiliary before subject**.","explanation":"Fronted **rarely** triggers **does she + prepare**; does carries present agreement.","keywords":["negative-fronting-present"],"skill":"negative-fronting-present","contextKey":"inversion-1","fingerprint":"4b90b2ad7d0eddb28968020a5ae5850e88e2d669394a1c0b83df30afed629a37","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-inversion"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["A fronted negative-frequency expression triggers **auxiliary before subject**.","Fronted **rarely** triggers **does she + prepare**; does carries present agreement.","Choose **does she prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Does carries agreement, so the main verb must lose -s.","B":"The auxiliary must precede the subject after fronted rarely.","C":"Fronted **rarely** triggers **does she + prepare**; does carries present agreement.","D":"This retains ordinary statement order instead of the requested inversion."}}},{"id":"98574840-d934-56d9-aef9-a104cdf4880c","topicSlug":"inversion","level":"C1","prompt":"Use formal inversion: “Never ____ the visitor guide so quickly.”","choices":[{"id":"A","text":"has they prepared"},{"id":"B","text":"have they prepared"},{"id":"C","text":"they have prepared"},{"id":"D","text":"have prepared they"}],"answerId":"B","hint":"Move **only have** in this perfect construction.","explanation":"Move the first auxiliary **have** before they; keep the participle after the subject.","keywords":["negative-fronting-perfect"],"skill":"negative-fronting-perfect","contextKey":"inversion-1","fingerprint":"33da2b7906e1ba2927965cc327241643e0dcb311ad95468de46fff0a5c7f533b","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-inversion"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Move **only have** in this perfect construction.","Move the first auxiliary **have** before they; keep the participle after the subject.","Choose **have they prepared**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Has does not agree with they.","B":"Move the first auxiliary **have** before they; keep the participle after the subject.","C":"This is ordinary statement order rather than the requested inversion.","D":"Only the first auxiliary moves; the participle stays after they."}}},{"id":"1c06fb75-6132-5c9b-a87d-104a7c3cc9db","topicSlug":"inversion","level":"C1","prompt":"Replace “If we had prepared the visitor guide”: “____ the visitor guide, we would have finished earlier.”","choices":[{"id":"A","text":"If had we prepared"},{"id":"B","text":"We had prepared"},{"id":"C","text":"Had we preparing"},{"id":"D","text":"Had we prepared"}],"answerId":"D","hint":"A formal unreal past condition can begin **Had + subject + participle**.","explanation":"Omit if and invert **had we** to express the unreal past condition.","keywords":["inverted-past-condition"],"skill":"inverted-past-condition","contextKey":"inversion-1","fingerprint":"d1e9b2cad7c80ad9087e09060268bdd55ba9c924d0d03b2fa3884641afd255d5","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-inversion"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["A formal unreal past condition can begin **Had + subject + participle**.","Omit if and invert **had we** to express the unreal past condition.","Choose **Had we prepared**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Do not combine if with this inverted conditional structure.","B":"Without if or inversion, this would not mark the requested conditional relationship.","C":"Had requires a past participle, not -ing.","D":"Omit if and invert **had we** to express the unreal past condition."}}},{"id":"100bc701-69ea-5439-a168-fd0deb4508ed","topicSlug":"inversion","level":"C1","prompt":"Use inversion in the main clause: “Only after the call ____ the visitor guide.”","choices":[{"id":"A","text":"she did prepare"},{"id":"B","text":"did she prepare"},{"id":"C","text":"she prepared"},{"id":"D","text":"did she prepared"}],"answerId":"B","hint":"The inversion belongs in the **main clause following only after**.","explanation":"Only after the call is a limiting opening; invert **did she** and use base prepare.","keywords":["only-after-scope"],"skill":"only-after-scope","contextKey":"inversion-1","fingerprint":"813cf2e90f4a2366750d02bbf9380c6688557fcaa3308090af2c17df192c3584","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-inversion"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The inversion belongs in the **main clause following only after**.","Only after the call is a limiting opening; invert **did she** and use base prepare.","Choose **did she prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The auxiliary must precede the subject in the inverted main clause.","B":"Only after the call is a limiting opening; invert **did she** and use base prepare.","C":"The requested formal main clause needs inversion after this limiting opening.","D":"Did already marks the past, so the next verb must be base."}}},{"id":"9d5e4722-8490-5d36-aefe-5b63e06a1bd3","topicSlug":"inversion","level":"C1","prompt":"Use formal inversion: “Rarely ____ the old portrait without help.”","choices":[{"id":"A","text":"she restores"},{"id":"B","text":"does she restores"},{"id":"C","text":"she does restore"},{"id":"D","text":"does she restore"}],"answerId":"D","hint":"A fronted negative-frequency expression triggers **auxiliary before subject**.","explanation":"Fronted **rarely** triggers **does she + restore**; does carries present agreement.","keywords":["negative-fronting-present"],"skill":"negative-fronting-present","contextKey":"inversion-2","fingerprint":"a9833daf11bb8341b9c27f18f4db03b680f0ae9c5b54e55c1ece5200b1ee7c38","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-inversion"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["A fronted negative-frequency expression triggers **auxiliary before subject**.","Fronted **rarely** triggers **does she + restore**; does carries present agreement.","Choose **does she restore**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"This retains ordinary statement order instead of the requested inversion.","B":"Does carries agreement, so the main verb must lose -s.","C":"The auxiliary must precede the subject after fronted rarely.","D":"Fronted **rarely** triggers **does she + restore**; does carries present agreement."}}},{"id":"c5e054bf-34ae-5c7f-aaee-7a55cceb53f5","topicSlug":"inversion","level":"C1","prompt":"Use formal inversion: “Never ____ the old portrait so quickly.”","choices":[{"id":"A","text":"has they restored"},{"id":"B","text":"have they restored"},{"id":"C","text":"they have restored"},{"id":"D","text":"have restored they"}],"answerId":"B","hint":"Move **only have** in this perfect construction.","explanation":"Move the first auxiliary **have** before they; keep the participle after the subject.","keywords":["negative-fronting-perfect"],"skill":"negative-fronting-perfect","contextKey":"inversion-2","fingerprint":"3873da47da722a77a977f97a2346d0bada5479cf3a83ca78b16e01c7148f49d5","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-inversion"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Move **only have** in this perfect construction.","Move the first auxiliary **have** before they; keep the participle after the subject.","Choose **have they restored**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Has does not agree with they.","B":"Move the first auxiliary **have** before they; keep the participle after the subject.","C":"This is ordinary statement order rather than the requested inversion.","D":"Only the first auxiliary moves; the participle stays after they."}}},{"id":"1b0d64b4-dbed-567b-ac92-5ce414163144","topicSlug":"inversion","level":"C1","prompt":"Replace “If we had restored the old portrait”: “____ the old portrait, we would have finished earlier.”","choices":[{"id":"A","text":"Had we restoring"},{"id":"B","text":"Had we restored"},{"id":"C","text":"If had we restored"},{"id":"D","text":"We had restored"}],"answerId":"B","hint":"A formal unreal past condition can begin **Had + subject + participle**.","explanation":"Omit if and invert **had we** to express the unreal past condition.","keywords":["inverted-past-condition"],"skill":"inverted-past-condition","contextKey":"inversion-2","fingerprint":"53fefdd5284ba53b82109fcaec8c04015c506d91b3f79dce5ccad77caf4228a0","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-inversion"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["A formal unreal past condition can begin **Had + subject + participle**.","Omit if and invert **had we** to express the unreal past condition.","Choose **Had we restored**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Had requires a past participle, not -ing.","B":"Omit if and invert **had we** to express the unreal past condition.","C":"Do not combine if with this inverted conditional structure.","D":"Without if or inversion, this would not mark the requested conditional relationship."}}},{"id":"7bd40f1a-272a-5aa5-a1f1-69dbfe911a2b","topicSlug":"inversion","level":"C1","prompt":"Use inversion in the main clause: “Only after the call ____ the old portrait.”","choices":[{"id":"A","text":"did she restored"},{"id":"B","text":"she did restore"},{"id":"C","text":"did she restore"},{"id":"D","text":"she restored"}],"answerId":"C","hint":"The inversion belongs in the **main clause following only after**.","explanation":"Only after the call is a limiting opening; invert **did she** and use base restore.","keywords":["only-after-scope"],"skill":"only-after-scope","contextKey":"inversion-2","fingerprint":"baf9aca17c039f21324471f327992e0571fb85d72d0bc184e993cce2a460c424","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-inversion"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The inversion belongs in the **main clause following only after**.","Only after the call is a limiting opening; invert **did she** and use base restore.","Choose **did she restore**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Did already marks the past, so the next verb must be base.","B":"The auxiliary must precede the subject in the inverted main clause.","C":"Only after the call is a limiting opening; invert **did she** and use base restore.","D":"The requested formal main clause needs inversion after this limiting opening."}}},{"id":"3c3178fb-880a-54ab-ac47-2fa39bb9aec2","topicSlug":"inversion","level":"C1","prompt":"Use formal inversion: “Rarely ____ the garden fence without help.”","choices":[{"id":"A","text":"she measures"},{"id":"B","text":"does she measures"},{"id":"C","text":"she does measure"},{"id":"D","text":"does she measure"}],"answerId":"D","hint":"A fronted negative-frequency expression triggers **auxiliary before subject**.","explanation":"Fronted **rarely** triggers **does she + measure**; does carries present agreement.","keywords":["negative-fronting-present"],"skill"